/* Private, shared-data mode for Pillar Campus. No child data is written to browser storage. */
var pillarLive = {
  client: null, session: null, member: null, campus: null, loaded: false,
  attendanceHistory: [], healthRecords: [], meals: [], papers: [], feePayments: [], queryErrors: [],
  pendingAttendance: new Set(), saveTimer: null, lastPaperId: null
};

function liveToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function liveDateOffset(offset){const d=new Date(`${liveToday()}T12:00:00+05:30`);d.setDate(d.getDate()+offset);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function liveDateLabel(){return new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date())}
function liveCan(...roles){return !!pillarLive.member&&roles.includes(pillarLive.member.role)}
function liveClearPrivateState(){students.splice(0);inventory.splice(0);staffDirectory.splice(0);leaveRecords=[];newRecords=[];pillarLive.attendanceHistory=[];pillarLive.healthRecords=[];pillarLive.stockRows=[];pillarLive.meals=[];pillarLive.papers=[];pillarLive.feePayments=[];pillarLive.pendingAttendance.clear();pillarLive.lastPaperId=null;paperQuestions=[];paperData={institution:'Pillar Campus',exam:'',className:'',subject:'',duration:'',date:''};currentPage='home'}
function liveMessage(message,success=false){const el=document.getElementById('authMessage');if(el){el.textContent=message;el.classList.toggle('success',success)}}
function liveSetBusy(busy){const button=document.querySelector('.auth-submit');if(button){button.disabled=busy;button.textContent=busy?'Please wait…':'Sign in securely'}}
function liveShowLogin(message=''){document.getElementById('appShell').hidden=true;document.getElementById('authScreen').hidden=false;document.getElementById('setupNotice').hidden=true;document.getElementById('loginForm').hidden=false;liveMessage(message)}
function liveSetSync(message,detail=''){const status=document.getElementById('syncStatus');const details=document.getElementById('syncDetails');if(status)status.textContent=message;if(details)details.textContent=detail}

async function liveSelect(tableName,columns,build){let q=pillarLive.client.from(tableName).select(columns);if(build)q=build(q);const {data,error}=await q;if(error){if(!['health_records','fee_payments'].includes(tableName)){pillarLive.queryErrors.push({tableName,message:error.message});console.warn(`Pillar Campus could not load ${tableName}:`,error.message)}return []}return data||[]}
function liveSetProfile(member,campus){const fullName=member.display_name||pillarLive.session.user.email||'Campus user';const initialsValue=initials(fullName)||'PC';document.getElementById('userName').textContent=fullName;document.getElementById('sideUserName').textContent=fullName;document.getElementById('userAvatar').textContent=initialsValue;document.getElementById('sideAvatar').textContent=initialsValue;document.getElementById('sideRole').textContent=member.role.replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());document.getElementById('campusName').textContent=campus.name;document.getElementById('campusLocation').textContent='Campus register';document.querySelector('.breadcrumbs').innerHTML=`<span>${esc(campus.name)}</span><i>/</i><b id="crumbCurrent">Overview</b>`;document.getElementById('syncLabel').textContent=`Private register · ${campus.name}`;document.getElementById('dateLabel').textContent=liveDateLabel()}

async function liveLoadWorkspace(session){
  if(!session||!pillarLive.client)return;
  if(pillarLive.loaded&&pillarLive.session?.user?.id===session.user.id)return;
  pillarLive.session=session;pillarLive.loaded=false;liveSetBusy(true);liveMessage('Opening your private campus register…',true);
  const memberResult=await pillarLive.client.from('campus_members').select('id,user_id,campus_id,display_name,phone,role,active').eq('user_id',session.user.id).eq('active',true).maybeSingle();
  if(memberResult.error||!memberResult.data){pillarLive.session=null;await pillarLive.client.auth.signOut();liveSetBusy(false);liveShowLogin('This account is not linked to a campus yet. Ask your director to finish the account setup.');return}
  pillarLive.member=memberResult.data;
  const campusResult=await pillarLive.client.from('campuses').select('id,name,slug').eq('id',pillarLive.member.campus_id).maybeSingle();
  if(campusResult.error||!campusResult.data){pillarLive.session=null;pillarLive.member=null;await pillarLive.client.auth.signOut();liveSetBusy(false);liveShowLogin('The campus link needs an administrator to review it.');return}
  pillarLive.campus=campusResult.data;liveSetProfile(pillarLive.member,pillarLive.campus);
  document.getElementById('authScreen').hidden=true;document.getElementById('appShell').hidden=false;
  try{await liveRefreshData();pillarLive.loaded=true;liveSetSync('Connected','Saved changes sync across this campus');render();liveMessage('',true)}catch(error){console.error('Pillar Campus could not open the campus register:',error);pillarLive.session=null;pillarLive.member=null;pillarLive.loaded=false;document.getElementById('appShell').hidden=true;await pillarLive.client.auth.signOut();liveSetBusy(false);liveShowLogin('Could not open the campus register. The database setup or connection needs attention.');return}
  liveSetBusy(false);
}

async function liveRefreshData(){
  if(!pillarLive.member||!pillarLive.client)return;
  pillarLive.queryErrors=[];liveSetSync('Syncing…','Loading the latest campus register');
  const today=liveToday(),from=liveDateOffset(-6);
  const requests=[
    liveSelect('campus_members','id,display_name,phone,role,active',q=>q.eq('campus_id',pillarLive.member.campus_id).eq('active',true).order('display_name')),
    liveSelect('students','id,roll_number,full_name,class_name,section,gender,residency,room,guardian_name,guardian_phone,active',q=>q.eq('campus_id',pillarLive.member.campus_id).eq('active',true).order('roll_number')),
    liveSelect('attendance','student_id,attendance_date,shift,status,marked_at',q=>q.eq('campus_id',pillarLive.member.campus_id).gte('attendance_date',from).lte('attendance_date',today).order('attendance_date')),
    liveSelect('leave_records','id,student_id,guardian_name,guardian_phone,purpose,expected_return,approved_by,actual_return,created_at',q=>q.eq('campus_id',pillarLive.member.campus_id).order('expected_return')),
    liveSelect('inventory_items','id,item_name,unit,quantity,minimum_quantity,updated_at',q=>q.eq('campus_id',pillarLive.member.campus_id).order('item_name')),
    liveSelect('stock_transactions','id,item_id,quantity_change,supplier,amount_paid,note,created_at',q=>q.eq('campus_id',pillarLive.member.campus_id).gte('created_at',`${from}T00:00:00+05:30`).order('created_at',{ascending:false}).limit(150)),
    liveSelect('meal_plans','id,meal_date,meal,menu,served',q=>q.eq('campus_id',pillarLive.member.campus_id).eq('meal_date',today).order('meal')),
    liveSelect('exam_papers','id,title,subject,class_name,exam_date,duration,questions,updated_at',q=>q.eq('campus_id',pillarLive.member.campus_id).order('updated_at',{ascending:false}).limit(10)),
    liveCan('director','admin','health_worker')?liveSelect('health_records','id,student_id,recorded_at,concern,care_given,follow_up_date,notes',q=>q.eq('campus_id',pillarLive.member.campus_id).order('recorded_at',{ascending:false}).limit(100)):Promise.resolve([]),
    liveCan('director','admin','bursar')?liveSelect('fee_payments','id,student_id,amount,purpose,method,paid_at',q=>q.eq('campus_id',pillarLive.member.campus_id).order('paid_at',{ascending:false}).limit(100)):Promise.resolve([])
  ];
  const [members,studentRows,attendanceRows,leaveRows,inventoryRows,stockRows,mealRows,paperRows,healthRows,paymentRows]=await Promise.all(requests);
  if(pillarLive.queryErrors.length)throw new Error(`Could not read ${pillarLive.queryErrors.map(e=>e.tableName).join(', ')}. Check the database setup and campus access rules.`);
  studentRows.sort((a,b)=>String(a.roll_number).localeCompare(String(b.roll_number),undefined,{numeric:true,sensitivity:'base'}));
  staffDirectory.splice(0,staffDirectory.length,...members.map(m=>({id:m.id,name:m.display_name,role:m.role.replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase()),phone:m.phone||''})));
  const todayById=new Map(attendanceRows.filter(a=>a.attendance_date===today&&a.shift===attendanceShift).map(a=>[a.student_id,a]));
  students.splice(0,students.length,...studentRows.map(s=>{const a=todayById.get(s.id);return {id:s.id,roll:s.roll_number,name:s.full_name,hindi:'',class:[s.class_name,s.section].filter(Boolean).join(' · '),room:s.residency==='resident'?(s.room||'Hostel'):'Day scholar',gender:s.gender||'',status:a?.status||'Not marked',time:a?new Date(a.marked_at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'—',tone:s.gender==='Girl'?'pink':'green',guardianName:s.guardian_name,guardianPhone:s.guardian_phone,residency:s.residency}}));
  inventory.splice(0,inventory.length,...inventoryRows.map(i=>({id:i.id,item:i.item_name,unit:i.unit,quantity:Number(i.quantity),minimum:Number(i.minimum_quantity),target:Math.max(Number(i.minimum_quantity)*2,Number(i.quantity),1),state:Number(i.quantity)<=Number(i.minimum_quantity)?'Buy soon':'In stock',used:''})));
  const memberById=new Map(members.map(m=>[m.id,m]));const studentById=new Map(studentRows.map(s=>[s.id,s]));
  leaveRecords=leaveRows.map(r=>{const student=studentById.get(r.student_id),approver=memberById.get(r.approved_by);return {id:r.id,student:student?.full_name||'Student',roll:student?.roll_number||'',guardianName:r.guardian_name,guardianPhone:r.guardian_phone,expectedReturn:r.expected_return,approvedBy:approver?.display_name||'Campus staff',staffPhone:approver?.phone||'',purpose:r.purpose,returned:!!r.actual_return,actualReturn:r.actual_return}});
  const awayIds=new Set(leaveRows.filter(r=>!r.actual_return).map(r=>r.student_id));students.forEach(s=>{if(awayIds.has(s.id)){s.status='On leave';s.time='—'}});
  pillarLive.attendanceHistory=attendanceRows;pillarLive.healthRecords=healthRows.map(h=>({...h,student:studentById.get(h.student_id)}));pillarLive.stockRows=stockRows;pillarLive.meals=mealRows;pillarLive.papers=paperRows;pillarLive.feePayments=paymentRows;
  if(paperRows.length){const latest=paperRows[0];pillarLive.lastPaperId=latest.id;paperData={institution:pillarLive.campus.name,exam:latest.title||'',className:latest.class_name||'',subject:latest.subject||'',duration:latest.duration||'',date:latest.exam_date||''};paperQuestions=Array.isArray(latest.questions)?latest.questions:[]}
  else{pillarLive.lastPaperId=null;paperData={institution:pillarLive.campus.name,exam:'',className:'',subject:'',duration:'',date:''};paperQuestions=[]}
  pillarLive.pendingAttendance.clear();liveSetSync('Connected','Saved changes sync across this campus');
}

function liveTopHeading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(pillarLive.campus?.name||'Pillar Campus')} <span>·</span> ${esc(liveDateLabel())}</p><h1>${title}</h1><p class="page-subtitle">${sub}</p></div><div class="heading-actions">${button('Refresh','refresh-data','button button-quiet','↻')}${actions}</div></div>`}
function liveStudentRows(rows,{attendance=false,actions=false,check=false,guardian=false}={}){return rows.map(s=>`<tr><td class="roll-number">${esc(s.roll)}</td><td><div class="student-cell"><span class="student-avatar ${esc(s.tone)}">${esc(initials(s.name))}</span><span class="student-meta"><b>${esc(s.name)}</b><small>${esc(s.class||'Class not set')}</small></span></div></td><td>${esc(s.room||'Day scholar')}</td>${guardian?`<td>${esc(s.guardianName||'—')}<br><small>${esc(s.guardianPhone||'')}</small></td>`:''}<td>${attendance?`<span class="status-pill ${s.status==='Present'?'status-present':s.status==='Absent'?'status-absent':s.status==='On leave'?'status-leave':'status-info'}">${esc(s.status)}</span>`:esc(s.gender||'—')}</td><td>${attendance?esc(s.time):s.room==='Day scholar'?'Day student':'Resident'}</td>${actions?`<td><button class="button button-small button-quiet" data-action="student-view" data-roll="${esc(s.roll)}">View</button></td>`:''}${check?`<td><button class="toggle-switch ${s.status!=='Present'?'off':''}" data-action="toggle-attendance" data-roll="${esc(s.roll)}" aria-label="Toggle ${esc(s.name)} attendance"><span></span></button></td>`:''}</tr>`).join('')}
function liveCountLabel(value,label){return `${value} ${label}${value===1?'':'s'}`}
function liveOverdue(){return leaveRecords.filter(r=>!r.returned&&daysOverdue(r)>0)}
function liveRenderHome(){const residents=students.filter(s=>s.residency==='resident').length,present=students.filter(s=>s.status==='Present').length,absent=students.filter(s=>s.status==='Absent').length,marked=present+absent,overdue=liveOverdue().length,low=inventory.filter(i=>i.quantity<=i.minimum).length,healthDue=pillarLive.healthRecords.filter(h=>h.follow_up_date&&h.follow_up_date<=liveToday()).length;const points=[];for(let n=6;n>=0;n--){const day=liveDateOffset(-n),rows=pillarLive.attendanceHistory.filter(a=>a.attendance_date===day&&a.shift==='Morning'),count=new Set(rows.map(a=>a.student_id)).size,all=students.length;points.push({day,rate:all?Math.round(count*100/all):0,records:rows.length,label:new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'short'}).format(new Date(`${day}T12:00:00+05:30`))})}const graph=students.length&&points.some(p=>p.records>0)?`<svg class="trend-chart" viewBox="0 0 420 130" role="img" aria-label="School attendance for the last seven days"><line class="grid-line" x1="34" y1="18" x2="410" y2="18"/><line class="grid-line" x1="34" y1="52" x2="410" y2="52"/><line class="grid-line" x1="34" y1="86" x2="410" y2="86"/><line class="grid-line" x1="34" y1="112" x2="410" y2="112"/><text x="0" y="21">100%</text><text x="7" y="55">70%</text><text x="7" y="89">40%</text><text x="7" y="115">0%</text>${(()=>{const coords=points.map((p,i)=>`${38+i*61} ${112-(p.rate/100)*94}`).join(' L ');return `<path class="trend-line" d="M${coords}"/>${points.map((p,i)=>`<circle class="trend-dot" cx="${38+i*61}" cy="${112-(p.rate/100)*94}" r="3.5"/><text x="${30+i*61}" y="127">${esc(p.label)}</text>`).join('')}`})()}</svg>`:`<div class="data-empty"><b>No attendance saved yet</b>Mark and save today's first register to start the trend.</div>`;return `${liveTopHeading(`Welcome, ${esc(pillarLive.member.display_name)} <span class="hindi-inline">خوش آمدید</span>`,'Today’s campus picture, from the shared register.',button('Open full report','go-reports','button button-quiet','↗'))}<section class="hero-card"><div class="hero-copy"><h2>Every child, cared for. <span>ہر بچہ، محفوظ۔</span></h2><p>Only records saved by your campus team appear here.</p></div><div class="hero-summary"><div class="hero-stat"><strong>${students.length}</strong><span>Children enrolled</span></div><div class="hero-stat"><strong>${residents}</strong><span>Living in hostel</span></div><div class="hero-stat"><strong>${staffDirectory.length}</strong><span>Staff accounts</span></div></div><div class="hero-actions">${button('Mark attendance','go-attendance','button button-primary','☑')}${liveCan('director','admin','teacher')?button('Add a student','add-student','button button-quiet','＋'):''}</div></section><section class="stats-grid">${stat('Present today',`${present} / ${students.length}`,`${marked} marked · ${students.length-marked} still to mark`,'✓')}${stat('Hostel residents',`${students.filter(s=>s.residency==='resident'&&s.status==='Present').length} / ${residents}`,'Morning/evening register','⌂','orange')}${stat('Health follow-ups',liveCan('director','admin','health_worker')?String(healthDue):'Private','Due today','＋','red')}${stat('Kitchen items to buy',String(low),`${liveOverdue().length} overdue leave return${overdue===1?'':'s'}`,'♨','blue')}</section><section class="dashboard-insights"><article class="card chart-card"><div class="chart-heading"><div><h3>School attendance trend <span class="hindi-inline">حاضری کا رجحان</span></h3><p>Saved morning attendance · last 7 days</p></div><span class="status-pill status-ok">${students.length?`${Math.round(present*100/students.length)}% today`:'Awaiting records'}</span></div>${graph}</article><article class="card chart-card"><div class="chart-heading"><div><h3>Campus at a glance</h3><p>${esc(liveDateLabel())} · real saved records</p></div><button class="text-link" data-action="go-hostel">View hostel →</button></div><div class="insight-splits"><div class="mini-insight"><span>Hostel check-in</span><b>${students.filter(s=>s.residency==='resident'&&s.status==='Present').length} / ${residents}</b><small>${residents?Math.round(students.filter(s=>s.residency==='resident'&&s.status==='Present').length*100/residents):0}% marked present</small><div class="mini-progress"><i style="width:${residents?Math.round(students.filter(s=>s.residency==='resident'&&s.status==='Present').length*100/residents):0}%"></i></div></div><div class="mini-insight"><span>Items below minimum</span><b>${low}</b><small>${inventory.length} items in kitchen register</small><div class="mini-progress"><i style="width:${inventory.length?Math.round((inventory.length-low)*100/inventory.length):0}%"></i></div></div></div><div class="live-chart-legend"><span><i></i> Saved attendance</span><span><i class="warn"></i> Stock needs a check</span></div></article></section><section class="dashboard-grid"><article class="card"><div class="card-header"><div><h3>Today’s attendance <span class="hindi-inline">آج کی حاضری</span></h3><p>${marked} of ${students.length} students marked</p></div><button class="text-link" data-action="go-attendance">Open register →</button></div><div class="attendance-content"><div class="attendance-metrics"><div class="ring-wrap"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="ring-bg" cx="50" cy="50" r="42"></circle><circle class="ring-fill" cx="50" cy="50" r="42" style="stroke-dashoffset:${263.9-(students.length?Math.round(present*100/students.length):0)*2.639}"></circle></svg><div class="ring-label"><b>${students.length?Math.round(present*100/students.length):0}%</b><small>present today</small></div></div><div class="att-breakdown"><div class="breakdown-item"><span class="legend-dot"></span><span>Present</span><b>${present}</b></div><div class="breakdown-item"><span class="legend-dot absent"></span><span>Absent</span><b>${absent}</b></div><div class="breakdown-item"><span class="legend-dot leave"></span><span>On leave</span><b>${students.filter(s=>s.status==='On leave').length}</b></div></div></div><div class="class-bars"><div class="class-bar-label"><span>Students with a saved mark</span><b>${marked} / ${students.length}</b></div><div class="bar-track"><span style="width:${students.length?Math.round(marked*100/students.length):0}%"></span></div></div></div></article><article class="card"><div class="card-header"><div><h3>Needs a little attention <span class="hindi-inline">توجہ دیں</span></h3><p>Follow up from today's records</p></div><button class="text-link" data-action="show-notifications">Open alerts →</button></div><div class="attention-list">${overdue?`<div class="attention-item"><span class="attention-icon hostel">⌂</span><div class="attention-copy"><b>${overdue} overdue leave return${overdue===1?'':'s'}</b><small>Tap the notification to call a saved family or staff number.</small></div><button class="text-link" data-action="show-notifications">Call</button></div>`:''}${low?`<div class="attention-item"><span class="attention-icon">♨</span><div class="attention-copy"><b>${low} kitchen item${low===1?'':'s'} below minimum</b><small>${inventory.filter(i=>i.quantity<=i.minimum).slice(0,3).map(i=>esc(i.item)).join(', ')}</small></div><button class="text-link" data-action="go-kitchen">Kitchen</button></div>`:''}${liveCan('director','admin','health_worker')&&healthDue?`<div class="attention-item"><span class="attention-icon health">＋</span><div class="attention-copy"><b>${healthDue} health follow-up${healthDue===1?'':'s'} due</b><small>Check with the health worker.</small></div><button class="text-link" data-action="go-health">Health</button></div>`:''}${!overdue&&!low&&!healthDue?'<div class="data-empty"><b>All caught up</b>Alerts appear here when a saved date or stock level needs follow-up.</div>':''}</div></article></section><section class="card table-card"><div class="card-header"><div><h3>Latest register entries <span class="hindi-inline">تازہ اندراجات</span></h3><p>Same roll order as the paper register</p></div><label class="search-box"><span>⌕</span><input id="homeSearch" placeholder="Find a student…" aria-label="Find a student"></label></div>${table(liveStudentRows(students.slice(0,8),{attendance:true}),{headers:['Roll no.','Student name','Class / room','Today','Marked at']})}<div class="table-footer"><span>${students.length?`Showing 1–${Math.min(8,students.length)} of ${students.length}`:'No student records yet'} · in roll order</span><button class="text-link" data-action="go-students">Open student register →</button></div></section>`}

function liveRenderAttendance(){const filtered=students.filter(s=>attendanceFilter==='All students'||attendanceFilter==='Girls'&&s.gender==='Girl'||attendanceFilter==='Boys'&&s.gender==='Boy'||attendanceFilter==='Hostel residents'&&s.residency==='resident').filter(s=>(`${s.name} ${s.roll} ${s.class}`).toLowerCase().includes(query.toLowerCase()));const marked=filtered.filter(s=>s.status!=='Not marked').length;return `${liveTopHeading('Attendance <span class="hindi-inline">حاضری</span>','Mark each child in the same order as the paper register.',button('Download register','download-attendance','button button-quiet','↓'))}<div class="summary-banner"><span class="banner-mark">☑</span><div><b>Paper register order stays the same</b><small>Save the morning or evening register to share it with your campus team.</small></div></div><div class="toolbar-line" style="justify-content:space-between;margin-bottom:12px"><div class="toolbar-line"><button class="filter-chip ${attendanceFilter==='All students'?'active':''}" data-action="filter-all">All · ${students.length}</button><button class="filter-chip ${attendanceFilter==='Girls'?'active':''}" data-action="filter-girls">Girls · ${students.filter(s=>s.gender==='Girl').length}</button><button class="filter-chip ${attendanceFilter==='Boys'?'active':''}" data-action="filter-boys">Boys · ${students.filter(s=>s.gender==='Boy').length}</button><button class="filter-chip ${attendanceFilter==='Hostel residents'?'active':''}" data-action="filter-hostel">Hostel · ${students.filter(s=>s.residency==='resident').length}</button></div><div class="attendance-tabs"><button class="${attendanceShift==='Morning'?'active':''}" data-action="shift-morning">Morning · صبح</button><button class="${attendanceShift==='Evening'?'active':''}" data-action="shift-evening">Evening · شام</button></div></div><div class="two-column"><section class="card table-card"><div class="card-header"><div><h3>${attendanceShift} attendance <span class="hindi-inline">${attendanceShift==='Morning'?'صبح کی حاضری':'شام کی حاضری'}</span></h3><p>${esc(liveDateLabel())} · by roll number</p></div><label class="search-box"><span>⌕</span><input id="attendanceSearch" value="${esc(query)}" placeholder="Search name or roll…" aria-label="Search name or roll"></label></div><div class="register-note"><span>↕</span> Start at the first roll number and mark each child who arrives.</div>${table(liveStudentRows(filtered,{attendance:true,check:true}),{headers:['Roll no.','Student name','Class / room','Today','Marked at','Here?']})}<div class="table-footer"><span>${marked} of ${filtered.length} marked · roll order</span><button class="text-link" data-action="mark-all">Mark all shown present →</button></div></section><div class="side-stack"><article class="info-card card"><h3>Today's total <span class="hindi-inline">آج</span></h3><p>Saved for ${attendanceShift.toLowerCase()} shift</p><div class="info-row"><span>Present</span><b>${filtered.filter(s=>s.status==='Present').length}</b></div><div class="info-row"><span>Absent</span><b>${filtered.filter(s=>s.status==='Absent').length}</b></div><div class="info-row"><span>On leave</span><b>${filtered.filter(s=>s.status==='On leave').length}</b></div><div class="info-row"><span>Still to mark</span><b>${Math.max(0,filtered.length-marked)}</b></div></article><article class="info-card card"><h3>Mark in one tap</h3><p>Use this after confirming all children are present.</p><button class="button button-small button-quiet" style="margin-top:10px" data-action="mark-all">Mark all shown as present</button></article></div></div><div class="save-bar"><span class="save-copy"><b id="pendingCount">${marked} children marked</b> · Save to share with your campus team.</span>${button('Save attendance','save-attendance','button button-primary','✓')}</div>`}

function liveRenderHostel(){const residents=students.filter(s=>s.residency==='resident'),active=leaveRecords.filter(r=>!r.returned);return `${liveTopHeading('Hostel & meals <span class="hindi-inline">ہاسٹل اور کھانا</span>','Morning and evening roll-call for resident children.',liveCan('director','admin','warden')?button('Add leave / outing','add-leave','button button-quiet','＋'):'') }<section class="stats-grid">${stat('Resident children',String(residents.length),'From the student register','⌂')}${stat('Checked in',String(residents.filter(s=>s.status==='Present').length),`${attendanceShift.toLowerCase()} attendance`,'✓','orange')}${stat('Away on leave',String(active.length),`${liveOverdue().length} overdue return(s)`,'↗','blue')}${stat('Meals planned',`${pillarLive.meals.filter(m=>m.served).length} / ${pillarLive.meals.length}`,`${pillarLive.meals.length} meal entries today`,'♨')}</section><div class="toolbar-line" style="justify-content:space-between;margin:7px 0 12px"><div class="attendance-tabs"><button class="${attendanceShift==='Morning'?'active':''}" data-action="shift-morning">Morning · صبح</button><button class="${attendanceShift==='Evening'?'active':''}" data-action="shift-evening">Evening · شام</button></div><span class="page-subtitle">${esc(liveDateLabel())} · in hostel roll order</span></div><div class="two-column"><section class="card table-card"><div class="card-header"><div><h3>Resident check-in <span class="hindi-inline">ہاسٹل حاضری</span></h3><p>Girls’ and boys’ hostel register</p></div><label class="search-box"><span>⌕</span><input id="hostelSearch" placeholder="Find a resident…" aria-label="Find a resident"></label></div><div class="register-note"><span>✓</span> Mark each child's arrival, then save the ${attendanceShift.toLowerCase()} list.</div>${table(liveStudentRows(residents,{attendance:true,check:true}),{headers:['Roll no.','Student name','Class / room','Today','Marked at','Here?']})}<div class="table-footer"><span>${residents.length} resident(s) · sorted by roll number</span><button class="text-link" data-action="save-hostel">Save check-in →</button></div></section><div class="side-stack"><article class="info-card card"><h3>Today’s meal plan <span class="hindi-inline">آج کا کھانا</span></h3><p>Menu shared by the kitchen</p><div class="meal-grid" style="margin-top:12px">${pillarLive.meals.length?pillarLive.meals.map(m=>`<div class="meal-card"><small>${esc(m.meal)}</small><b>${esc(m.menu||'Menu not entered')}</b><button class="text-link" data-action="meal-toggle" data-meal-id="${esc(m.id)}">${m.served?'Served ✓':'Mark served'}</button></div>`).join(''):'<div class="data-empty">No meals added for today.</div>'}</div><button class="button button-small button-quiet" style="margin-top:9px" data-action="add-meal">＋ Add meal</button></article><article class="info-card card"><h3>Children away from campus</h3><p>Expected return dates and family contact</p>${active.length?active.map(r=>`<div class="info-row"><span>${esc(r.student)} · Roll ${esc(r.roll)}</span><b>${daysOverdue(r)?`Late ${daysOverdue(r)} day(s)`:`Back ${esc(r.expectedReturn)}`}</b><button class="text-link" data-action="return-leave" data-leave-id="${esc(r.id)}">Returned</button></div>`).join(''):'<div class="info-row"><span>No active leave records</span><b>✓</b></div>'}${liveOverdue().length?`<div class="notification-entry overdue"><b>${liveOverdue().length} return date(s) passed</b><p>Open the notification and tap a saved phone number to call.</p><button class="button button-small button-quiet" data-action="show-notifications">Open notification</button></div>`:''}</article></div></div>`}

function liveRenderStudents(){const rows=students.filter(s=>(`${s.name} ${s.roll} ${s.class} ${s.guardianName}`).toLowerCase().includes(query.toLowerCase()));const residents=students.filter(s=>s.residency==='resident').length;return `${liveTopHeading('Students <span class="hindi-inline">طلبہ</span>','Keep a child, paper roll number, and family contact together.',liveCan('director','admin','teacher')?button('Add a student','add-student','button button-primary','＋'):'') }<section class="stats-grid">${stat('Enrolled children',String(students.length),'Active student records','♧')}${stat('Hostel residents',String(residents),'From residence register','⌂','blue')}${stat('Girls',String(students.filter(s=>s.gender==='Girl').length),'Student register','♡')}${stat('Family contact saved',String(students.filter(s=>s.guardianName&&s.guardianPhone).length),`${students.filter(s=>!s.guardianPhone).length} phone(s) still to add`,'☎','orange')}</section><section class="card table-card"><div class="card-header"><div><h3>Student register <span class="hindi-inline">بچوں کا رجسٹر</span></h3><p>Search by a child, guardian, or paper roll number.</p></div><div class="table-toolbar"><label class="search-box"><span>⌕</span><input id="studentsSearch" value="${esc(query)}" placeholder="Name or roll no.…" aria-label="Search students"></label><button class="select-small" data-action="export-students">Download list ↓</button></div></div>${table(liveStudentRows(rows,{guardian:true,actions:true}),{headers:['Roll no.','Student name','Class / room','Parent / guardian','Gender','Stay','']})}<div class="table-footer"><span>${rows.length} of ${students.length} · sorted by paper roll number</span><button class="text-link" data-action="add-student">＋ Add a student</button></div></section><p class="page-subtitle" style="margin-top:10px">Keep family contact details current so staff can reach the right person.</p>`}

function liveRenderHealth(){if(!liveCan('director','admin','health_worker'))return `${liveTopHeading('Student health <span class="hindi-inline">طلبہ کی صحت</span>','Private care notes are available only to the director, admin, and health worker.') }<div class="summary-banner"><span class="banner-mark" style="background:#fae4e2;color:#b75b53">＋</span><div><b>Private student health register</b><small>Only authorised health staff and campus directors can open these notes.</small></div>${button('Add a health visit','add-health','button button-primary','＋')}</div><section class="stats-grid">${stat('Follow-ups due',String(pillarLive.healthRecords.filter(h=>h.follow_up_date&&h.follow_up_date<=liveToday()).length),'Review with the health worker','＋','red')}${stat('Visits recorded this month',String(pillarLive.healthRecords.filter(h=>String(h.recorded_at).slice(0,7)===liveToday().slice(0,7)).length),'Saved care notes','✓')}${stat('Students with records',String(new Set(pillarLive.healthRecords.map(h=>h.student_id)).size),'Confidential to authorised staff','♡','blue')}${stat('Follow-up dates set',String(pillarLive.healthRecords.filter(h=>h.follow_up_date).length),'Check the next visit date','☾','orange')}</section><section class="card table-card"><div class="card-header"><div><h3>Recent health visits <span class="hindi-inline">صحت کی تازہ معلومات</span></h3><p>Private notes · sorted newest first</p></div><label class="search-box"><span>⌕</span><input id="healthSearch" value="${esc(query)}" placeholder="Find a child…" aria-label="Find a child"></label></div>${pillarLive.healthRecords.length?table(pillarLive.healthRecords.filter(h=>(`${h.student?.full_name||''} ${h.concern}`).toLowerCase().includes(query.toLowerCase())).map(h=>`<tr><td>${new Date(h.recorded_at).toLocaleDateString('en-IN')}</td><td>${esc(h.student?.roll_number||'—')}</td><td>${esc(h.student?.full_name||'Student')}</td><td>${esc(h.concern)}</td><td>${esc(h.care_given||'—')}</td><td>${h.follow_up_date?esc(h.follow_up_date):'—'}</td></tr>`).join(''),{headers:['Date','Roll','Student','Concern','Care given','Follow-up']}):'<div class="data-empty"><b>No health records saved</b>Add a health visit to begin the private register.</div>'}</section>`}

function liveRenderKitchen(){const low=inventory.filter(i=>i.quantity<=i.minimum),items=inventory.map(i=>{const pct=i.target?Math.min(100,Math.round(i.quantity*100/i.target)):0;return `<tr><td><div class="inventory-name"><span class="inventory-icon">◉</span><span class="inventory-meta"><b>${esc(i.item)}</b><small>Minimum ${i.minimum} ${esc(i.unit)}</small></span></div></td><td>${i.quantity} ${esc(i.unit)}</td><td><div class="stock-meter"><div class="bar-track"><span style="width:${pct}%"></span></div><small>${pct}% of target</small></div></td><td><span class="status-pill ${i.quantity<=i.minimum?'status-low':'status-ok'}">${i.quantity<=i.minimum?'Buy soon':'In stock'}</span></td><td>${liveCan('director','admin','kitchen')?`<button class="button button-small button-quiet" data-action="stock-update" data-item="${esc(i.id)}">Update stock</button>`:'—'}</td></tr>`}).join('');return `${liveTopHeading('Kitchen stock <span class="hindi-inline">باورچی خانے کا ذخیرہ</span>','Track groceries and know what is below the minimum.',liveCan('director','admin','kitchen')?`${button('Add an item','add-stock','button button-quiet','＋')}${button('Record delivery','add-delivery','button button-primary','♨')}`:'') }<section class="stats-grid">${stat('Items on the list',String(inventory.length),'Kitchen stock register','♨')}${stat('Below minimum',String(low.length),'Plan the next purchase','!','orange')}${stat('Deliveries this week',String(pillarLive.stockRows.filter(r=>Number(r.quantity_change)>0).length),'From saved stock notes','↓','blue')}${stat('Kitchen spend this week',`₹${pillarLive.stockRows.reduce((n,r)=>n+Number(r.amount_paid||0),0).toLocaleString('en-IN')}`,'Saved grocery purchases','₹')}</section><section class="card table-card"><div class="card-header"><div><h3>Grocery store list <span class="hindi-inline">راشن کا رجسٹر</span></h3><p>Current quantity against each item's minimum</p></div><button class="select-small" data-action="kitchen-export">Download list ↓</button></div>${inventory.length?table(items,{headers:['Food item','Quantity left','Stock level','Status',''] }):'<div class="data-empty"><b>No kitchen items saved</b>Add rice, dal, oil, and other regular groceries.</div>'}<div class="table-footer"><span>${low.length?`${low.length} item(s) need buying`:'All saved items are above minimum'} · latest update shared with the director</span><button class="text-link" data-action="buying-list">Make buying list →</button></div></section><section class="card table-card" style="margin-top:14px"><div class="card-header"><div><h3>Recent deliveries</h3><p>Last 20 stock movements</p></div></div>${pillarLive.stockRows.length?table(pillarLive.stockRows.slice(0,20).map(t=>{const item=inventory.find(i=>i.id===t.item_id);return `<tr><td>${new Date(t.created_at).toLocaleDateString('en-IN')}</td><td>${esc(item?.item||'Grocery item')}</td><td>${Number(t.quantity_change)>0?'+':''}${Number(t.quantity_change)} ${esc(item?.unit||'')}</td><td>${esc(t.supplier||t.note||'—')}</td><td>${t.amount_paid?`₹${Number(t.amount_paid).toLocaleString('en-IN')}`:'—'}</td></tr>`}).join(''),{headers:['Date','Item','Change','Supplier / note','Amount']}):'<div class="data-empty">No deliveries saved yet.</div>'}</section>`}

function liveRenderReports(){const last7=[];for(let n=6;n>=0;n--){const day=liveDateOffset(-n),rows=pillarLive.attendanceHistory.filter(a=>a.attendance_date===day&&a.shift==='Morning'),present=new Set(rows.filter(a=>a.status==='Present').map(a=>a.student_id)).size;last7.push({day,records:rows.length,label:new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'short'}).format(new Date(`${day}T12:00:00+05:30`)),present,records:rows.length,pct:students.length?Math.round(present*100/students.length):0})}return `${liveTopHeading('Reports & insights <span class="hindi-inline">رپورٹس اور معلومات</span>','Clear summaries from campus records saved by your team.',button('Download attendance CSV','report-export','button button-quiet','↓'))}<section class="report-grid">${stat('Children enrolled',String(students.length),'Active student register','♧')}${stat('Attendance marked today',String(students.filter(s=>s.status!=='Not marked').length),`of ${students.length} students`,'✓')}${stat('Hostel residents',String(students.filter(s=>s.residency==='resident').length),'Current resident list','⌂')}${stat('Open leave records',String(leaveRecords.filter(l=>!l.returned).length),'Expected return date recorded','↗')}${liveCan('director','admin','kitchen')?stat('Kitchen stock value',`₹${pillarLive.stockRows.reduce((sum,r)=>sum+Number(r.amount_paid||0),0).toLocaleString('en-IN')}`,'Saved grocery purchases','₹'):''}${liveCan('director','admin','bursar')?stat('Fees received',`₹${pillarLive.feePayments.reduce((sum,r)=>sum+Number(r.amount||0),0).toLocaleString('en-IN')}`,'Recent saved payments','₹','blue'):''}</section><section class="card chart-card"><div class="chart-heading"><div><h3>Attendance over the last 7 days <span class="hindi-inline">گزشتہ سات دن کی حاضری</span></h3><p>Morning register · percentage of active students</p></div></div>${last7.some(x=>x.records>0)?`<div class="class-bars" style="grid-template-columns:repeat(7,minmax(0,1fr));margin:24px 8px 10px">${last7.map(x=>`<div><div class="class-bar-label"><span>${esc(x.label)}</span><b>${x.pct}%</b></div><div class="bar-track"><span style="width:${x.pct}%"></span></div><small>${x.present} present</small></div>`).join('')}</div>`:'<div class="data-empty"><b>No attendance trend yet</b>Save daily attendance to build this graph.</div>'}</section><section class="card chart-card" style="margin-top:14px"><div class="chart-heading"><div><h3>Student register by stay type</h3><p>Current enrolment</p></div></div><div class="class-bars" style="grid-template-columns:repeat(2,minmax(0,1fr));margin:24px 8px 8px"><div><div class="class-bar-label"><span>Hostel residents</span><b>${students.filter(s=>s.residency==='resident').length}</b></div><div class="bar-track"><span style="width:${students.length?Math.round(students.filter(s=>s.residency==='resident').length*100/students.length):0}%"></span></div></div><div><div class="class-bar-label"><span>Day students</span><b>${students.filter(s=>s.residency!=='resident').length}</b></div><div class="bar-track"><span style="width:${students.length?Math.round(students.filter(s=>s.residency!=='resident').length*100/students.length):0}%"></span></div></div></div></section>`}

function liveRenderStaff(){return `${liveTopHeading('Our staff <span class="hindi-inline">ہمارا عملہ</span>','Campus contacts used for follow-up and attendance handover.') }<section class="summary-banner"><span class="banner-mark">♙</span><div><b>${staffDirectory.length} staff account(s) linked</b><small>To add an account, invite the person in Supabase and assign their campus role as described in the setup guide.</small></div></section><section class="card table-card"><div class="card-header"><div><h3>Staff contact register <span class="hindi-inline">عملے کے رابطے</span></h3><p>These are the approved names available in the leave form.</p></div></div>${staffDirectory.length?table(staffDirectory.map(m=>`<tr><td><div class="student-cell"><span class="student-avatar green">${esc(initials(m.name))}</span><span class="student-meta"><b>${esc(m.name)}</b><small>${esc(m.role)}</small></span></div></td><td>${esc(m.role)}</td><td>${m.phone?`<a class="notification-contact ltr-number" href="tel:${esc(m.phone)}">☎ ${esc(m.phone)}</a>`:'Phone not added'}</td><td>${m.id===pillarLive.member.id?'<span class="status-pill status-ok">You</span>':'Campus member'}</td></tr>`).join(''),{headers:['Staff member','Role','Phone','Account']}):'<div class="data-empty">No staff accounts are linked yet.</div>'}<div class="table-footer"><span>Only the director/admin can assign roles through the database setup.</span></div></section>`}

function liveRenderFees(){if(!liveCan('director','admin','bursar'))return `${liveTopHeading('Fees & family support <span class="hindi-inline">فیس اور خاندان</span>','Payment records are private to the director, admin, and bursar.')}`;return `${liveTopHeading('Fees & family support <span class="hindi-inline">فیس اور خاندان</span>','Save family payments with a clear purpose and receipt.',button('Record a payment','add-payment','button button-primary','＋'))}<section class="stats-grid">${stat('Payments in register',String(pillarLive.feePayments.length),'Recent payments','₹')}${stat('Amount recorded',`₹${pillarLive.feePayments.reduce((n,p)=>n+Number(p.amount||0),0).toLocaleString('en-IN')}`,'Recent payment records','✓')}${stat('Students with records',String(new Set(pillarLive.feePayments.map(p=>p.student_id)).size),'Family payment history','♧')}${stat('Payment methods',String(new Set(pillarLive.feePayments.map(p=>p.method)).size),'Cash, UPI, or other','₹','blue')}</section><section class="card table-card"><div class="card-header"><div><h3>Recent family payments</h3><p>Only authorised finance staff can see this register.</p></div></div>${pillarLive.feePayments.length?table(pillarLive.feePayments.map(p=>{const s=students.find(x=>x.id===p.student_id);return `<tr><td>${esc(s?.roll||'—')}</td><td>${esc(s?.name||'Student')}<br><small>${esc(s?.guardianName||'')}</small></td><td>${esc(p.purpose)}</td><td>₹${Number(p.amount).toLocaleString('en-IN')}</td><td>${new Date(p.paid_at).toLocaleDateString('en-IN')} · ${esc(p.method)}</td><td><button class="button button-small button-quiet" data-action="receipt" data-payment-id="${esc(p.id)}">Receipt</button></td></tr>`}).join(''),{headers:['Roll no.','Student / family','For','Amount','Date · method','']}):'<div class="data-empty"><b>No payments saved yet</b>Record a family payment to start this register.</div>'}</section>`}

function liveRender(){if(!pillarLive.session||!pillarLive.member)return;const renderer={home:liveRenderHome,attendance:liveRenderAttendance,hostel:liveRenderHostel,students:liveRenderStudents,papers:renderQuestionPapers,health:liveRenderHealth,kitchen:liveRenderKitchen,reports:liveRenderReports,staff:liveRenderStaff,fees:liveRenderFees};document.getElementById('contentArea').innerHTML=(renderer[currentPage]||liveRenderHome)();const pageTitle=document.querySelector('.page-heading h1'),pageSubtitle=document.querySelector('.page-heading .page-subtitle');if(currentLanguage!=='en'){if(pageTitle)pageTitle.textContent=featureTitles[currentLanguage]?.[currentPage]||pages[currentPage]?.[0]||'Overview';if(pageSubtitle&&featureSubtitles[currentLanguage]?.[currentPage])pageSubtitle.textContent=featureSubtitles[currentLanguage][currentPage]}document.getElementById('crumbCurrent').textContent=featureTitles[currentLanguage]?.[currentPage]||pages[currentPage]?.[0]||'Overview';document.querySelectorAll('.nav-item').forEach(n=>{n.classList.toggle('active',n.dataset.page===currentPage);const label=n.querySelector('.nav-copy b');if(label)label.textContent=featureTitles[currentLanguage]?.[n.dataset.page]||pages[n.dataset.page]?.[0]||''});bindInputs();if(currentPage==='papers')bindPaperInputs();const badge=document.getElementById('notificationButton');if(badge){const overdue=liveOverdue().length;badge.setAttribute('aria-label',`${overdue} overdue leave notification(s)`);const dot=badge.querySelector('i');if(dot)dot.style.display=overdue?'block':'none'}}
function liveRoleLabel(role){return (role||'staff').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase())}
function liveTop(){document.getElementById('dateLabel').textContent=liveDateLabel();document.getElementById('breadcrumbs').innerHTML=`<span>${esc(pillarLive.campus?.name||'Pillar Campus')}</span><i>/</i><b id="crumbCurrent">${esc(pages[currentPage]?.[0]||'Overview')}</b>`}

